"""Release lifetime and flow-epoch replay.

Installs are atomic: a failed attempt leaves the current release and every
resident bank untouched.  A bank is resident while it is current or pinned by
at least one open epoch, and each release id occupies exactly one bank.
Classified epochs keep their pin until close, and every open must close inside
the request.
"""
from formats import InvalidRequest

PADDING = 1514


class Flow:
    __slots__ = ('active', 'release', 'epoch', 'features', 'last', 'done', 'source')

    def __init__(self, release, epoch):
        self.active = True
        self.release = release
        self.epoch = epoch
        self.features = []
        self.last = None
        self.done = False
        self.source = None


class Engine:
    def __init__(self, models, capacity):
        self.models = models
        self.capacity = capacity
        self.current = None
        self.resident = set()
        self.refs = {}
        self.flows = {}
        self.epochs = {}
        self.installs = []
        self.decisions = []

    # -- pool bookkeeping ---------------------------------------------------
    def usage_of(self, members):
        used_range = 0
        used_exact = 0
        for mid in members:
            model = self.models[mid]
            if model['mode'] == 'range':
                used_range += model['entries']
            else:
                used_exact += model['entries']
        return {'range': used_range, 'exact': used_exact}

    def usage(self):
        return self.usage_of(self.resident)

    def evictable(self, mid, keep):
        """A previous current bank with no open epoch reference can go."""
        return mid is not None and mid != keep and self.refs.get(mid, 0) == 0

